"""Synthetic failure controls plus frozen main-snapshot ACTUAL_PERSON bytes.

Actual controls: B44 independently completed28 source records, snapshot
8ff7b7053760d72f9389fbe8ef36b00a46a3a08cb40a477234006df2330d70d3,
raw component SHA4d563471a32d61d36faf78f1302597cb82e9e8c56ca870234d6ec797c62d58e0.
All observed primary kinds are0; null/basic/other-type cases below are synthetic.
"""
from datetime import date
import struct

import pytest

from fm_live_mcp.saved_primary_contract import read_primary_contract, MAX_ROWS


def packed(value):
    value = date.fromisoformat(value)
    return struct.pack('<I', value.year << 16 | value.timetuple().tm_yday)


def header(kind=0, *, slots=1, name_count=0):
    return bytes(25) + bytes([name_count]) + bytes(name_count * 4) + bytes(4) + bytes([slots]) + struct.pack('<b', kind)


def basic(owner=7):
    return struct.pack('<I', owner) + bytes(8 + 7)


def full(owner=7, *, status=1, dynamic=False, rows80=0, rows98=0, numeric=0):
    clause = struct.pack('<ihBB', -1, 1, 22, 0)
    prefix = (struct.pack('<b', status) + bytes(16 + 8 + 1 + 2) + b'\x01' + clause +
              bytes([rows80]) + bytes(31 * rows80) + bytes([bool(rows98)]))
    if rows98:
        prefix += struct.pack('<I', rows98) + (b'\x01\0' + bytes(13)) * rows98
    prefix += bytes(4 + 1)
    extra = b'\x03' + struct.pack('<I', 4) + bytes(8)
    shared = (bytes(12) + packed('2031-06-30') + bytes(4 + 6) + struct.pack('<I', numeric) +
              (b'\x07' + bytes(28)) * numeric + b'\0' + packed('2030-07-01') + bytes(7) +
              (b'\0\0\0\x08' + bytes(4) if dynamic else bytes(8)) + bytes(4 + 1) + basic(owner))
    return prefix + extra + shared


def frame(**kwargs):
    return header() + full(**kwargs)


def test_fixed_dates_status_owner_and_stored_option():
    raw = frame(rows80=1, rows98=1, numeric=2)
    out = read_primary_contract(raw, 0, len(raw), person_index=7)
    assert out['state'] == 'available' and out['owner_person_index'] == 7
    assert out['contract_dates'] == {'last_signed': '2030-07-01', 'expires': '2031-06-30', 'state': 'fixed_expiry'}
    assert out['contract_status'] == {'native_code': 1, 'title': 'Full Time', 'state': 'decoded'}
    assert out['counts']['rows80'] == out['counts']['rows98'] == 1
    assert out['counts']['numeric_rows'] == 2
    assert out['stored_club_extension_options'][0]['years_raw_signed16'] == 1
    assert not out['extension_activation_evaluated']
    assert out['primary_contract_wire_complete'] and not out['complete_actual_person']
    assert out['wire_profile_is_conditional'] and not out['native_loader_acceptance_proved']


def test_all_strict_truncations_cannot_reach_dates_from_outside_common_bound():
    raw = frame(rows80=1, rows98=1, numeric=2)
    for end in range(1, len(raw)):
        out = read_primary_contract(raw + bytes(1000), 0, end, person_index=7)
        assert out['state'] == 'unsupported' and out['contract_dates'] is None, end


def test_later_offer_or_auxiliary_bytes_are_not_used():
    raw = frame()
    first = read_primary_contract(raw + bytes(100), 0, len(raw) + 100, person_index=7)
    second = read_primary_contract(raw + b'\xff' * 100, 0, len(raw) + 100, person_index=7)
    assert first == second
    assert first['source_end'] == len(raw)


def test_dynamic_expiry_retains_signed_date_but_does_not_use_stored_expiry():
    raw = bytearray(frame(dynamic=True))
    known = read_primary_contract(raw, 0, len(raw), person_index=7)
    expiry_at = known['source_offsets']['expires']
    raw[expiry_at:expiry_at + 4] = bytes(4)
    out = read_primary_contract(raw, 0, len(raw), person_index=7)
    assert out['state'] == 'dynamic_expiry'
    assert out['contract_dates']['expires'] is None and out['contract_dates']['last_signed'] == '2030-07-01'
    assert out['reason'] == 'dynamic_expiry_requires_independent_date_anchor'


def test_synthetic_explicit_null_is_distinct_from_no_serialized_primary_slot():
    null = header(-1)
    out = read_primary_contract(null, 0, len(null), person_index=7)
    assert out['state'] == 'no_current_contract' and out['source_kind'] == -1
    no_slot = header()[:-1]
    no_slot = no_slot[:-1] + b'\0'
    out = read_primary_contract(no_slot, 0, len(no_slot), person_index=7)
    assert out['state'] == 'unsupported'
    assert out['reason'] == 'primary_slot_not_serialized_or_unsupported_count'


@pytest.mark.parametrize('kind', [1, 2, 3, 4, 5, 6, -2])
def test_synthetic_other_primary_types_are_not_full_contracts(kind):
    raw = header(kind) + basic()
    out = read_primary_contract(raw, 0, len(raw), person_index=7)
    assert out['state'] == 'unsupported' and out['source_kind'] == kind
    assert out['contract_dates'] is None
    if kind == 5:
        assert out['owner_person_index'] == 7
        assert out['reason'] == 'basic_contract_date_fields_unavailable'


def test_source_owner_is_checked_without_native_id_or_nonzero_rules():
    raw = frame(owner=0)
    assert read_primary_contract(raw, 0, len(raw), person_index=0)['state'] == 'available'
    out = read_primary_contract(raw, 0, len(raw), person_index=7)
    assert out['state'] == 'unsupported' and 'owner_ordinal_mismatch' in out['reason']


def test_unmapped_signed_status_is_preserved_beside_valid_dates():
    raw = frame(status=-1)
    out = read_primary_contract(raw, 0, len(raw), person_index=7)
    assert out['state'] == 'available'
    assert out['contract_status'] == {'native_code': -1, 'title': None, 'state': 'unmapped_native_status'}


@pytest.mark.parametrize('kwargs', [{'source_major': True}, {'source_major': 3725}, {'minor': 8}, {'reference_mode': 'raw32'}])
def test_unsupported_source_profiles_are_explicit(kwargs):
    raw = frame()
    out = read_primary_contract(raw, 0, len(raw), person_index=7, **kwargs)
    assert out['state'] == 'unsupported' and out['reason'] == 'unsupported_primary_contract_source_profile'


def test_current_writer_versions_and_variable_budgets_fail_closed():
    raw = bytearray(frame(rows98=1, numeric=1))
    known = read_primary_contract(raw, 0, len(raw), person_index=7)
    row98 = next(r for r in known['checked_ranges'] if r['reader'] == '1279E3C')
    extra = next(r for r in known['checked_ranges'] if r['reader'] == 'FE4470')
    numeric = next(r for r in known['checked_ranges'] if r['reader'] == '1543D60')
    for offset, value in ((row98['start'], 2), (extra['start'], 2), (numeric['start'], 6)):
        bad = bytearray(raw)
        bad[offset] = value
        out = read_primary_contract(bad, 0, len(bad), person_index=7)
        assert out['state'] == 'unsupported' and out['contract_dates'] is None
    bad = bytearray(raw)
    struct.pack_into('<I', bad, row98['start'] - 4, MAX_ROWS + 1)
    assert read_primary_contract(bad, 0, len(bad), person_index=7)['reason'] == 'primary_contract_count_budget'
    bad = bytearray(raw)
    struct.pack_into('<I', bad, extra['start'] + 1, 0xffffffff)
    assert read_primary_contract(bad, 0, len(bad), person_index=7)['reason'] == 'FE4470_byte_budget'


def test_invalid_fixed_packed_date_is_not_a_renewal_date():
    raw = bytearray(frame())
    known = read_primary_contract(raw, 0, len(raw), person_index=7)
    at = known['source_offsets']['expires']
    raw[at:at + 4] = bytes(4)
    out = read_primary_contract(raw, 0, len(raw), person_index=7)
    assert out['state'] == 'unsupported' and out['contract_dates'] is None


@pytest.mark.parametrize('start,end,index', [(True, 100, 7), (-1, 100, 7), (0, 999, 7), (10, 2, 7), (0, 100, True)])
def test_invalid_explicit_boundaries_raise(start, end, index):
    with pytest.raises(ValueError):
        read_primary_contract(bytes(200), start, end, person_index=index)


