@pytest.mark.parametrize('control', ACTUAL_CONTROLS)
def test_frozen_actual_primary_contract(control):
    ordinal, raw_hex, expiry, signed, options, relative_primary_end = control
    raw = bytes.fromhex(raw_hex)
    out = read_primary_contract(raw, 0, len(raw), person_index=ordinal)
    assert out['state'] == 'available' and out['owner_person_index'] == ordinal
    assert out['contract_dates'] == {'last_signed': signed, 'expires': expiry, 'state': 'fixed_expiry'}
    assert out['contract_status']['native_code'] == 1
    assert out['source_end'] == relative_primary_end
    assert [x['years_raw_signed16'] for x in out['stored_club_extension_options']] == options


@pytest.mark.parametrize('kind', [0, 5])
@pytest.mark.parametrize('amount', [-1, 0, 12121, 2147483647])
@pytest.mark.parametrize('currency', [None, 'GBP'])
def test_primary_weekly_wage_preserves_signed_word_and_currency_evidence(kind, amount, currency):
    raw = bytearray(frame() if kind == 0 else header(5) + basic())
    wage_at = len(raw) - 7
    struct.pack_into('<i', raw, wage_at, amount)
    out = read_primary_contract(raw, 0, len(raw), person_index=7, base_currency_code=currency)
    wage = out['weekly_wage']
    assert out['owner_person_index'] == 7 and out['primary_contract_wire_complete']
    assert wage['source_offset'] == wage_at and wage['stored_signed_amount'] == amount
    assert wage['amount'] == (None if amount < 0 else amount)
    assert wage['period'] == 'week' and wage['currency'] == currency
    assert wage['state'] == ('unsupported_negative_amount' if amount < 0 else
                             'base_currency_unverified' if currency is None else 'decoded')


def test_no_wage_without_full_owned_contract_envelope():
    raw = header(5, slots=3) + basic()
    for kwargs, source in [({'person_index': 7}, raw),
                           ({'person_index': 8}, frame()), ({'person_index': 7}, header(-1))]:
        assert read_primary_contract(source, 0, len(source), **kwargs)['weekly_wage'] is None
